<body>

<header class="header">
  <a href="index.html" class="header-logo">StreamWave</a>
</header>

<main class="login-main">
  <div class="login-card">
    <h1>Enter your info to sign in</h1>
    <p class="login-sub">Or get started with a new account.</p>

    <form onsubmit="event.preventDefault(); handleLogin(this);" novalidate>
      <div class="form-group">
        <label for="login-email">Email address or mobile number</label>
        <input id="login-email" type="text" placeholder="Email address or mobile number" required autocomplete="username">
      </div>
      <div class="form-group">
        <label for="login-password">Password</label>
        <input id="login-password" type="password" placeholder="Password" required autocomplete="current-password">
      </div>
      <button type="submit" class="btn-continue">Continue</button>
    </form>

    <div class="help-area">
      <button class="help-toggle" onclick="toggleHelp()" id="helpBtn" aria-expanded="false">Get help</button>
