</footer>

<script>
function toggleHelp() {
  const content = document.getElementById('helpContent');
  const btn = document.getElementById('helpBtn');
  const isOpen = content.classList.toggle('open');
  btn.setAttribute('aria-expanded', isOpen);
}

function handleLogin(form) {
  const email = form.querySelector('#login-email').value.trim();
  const password = form.querySelector('#login-password').value;

  if (!email) {
    alert('Please enter your email address or mobile number.');
    return;
  }
  if (!password) {
    alert('Please enter your password.');
    return;
  }

  alert('Sign-in simulation: credentials submitted for ' + email);
  form.reset();
  document.getElementById('helpContent').classList.remove('open');
  document.getElementById('helpBtn').setAttribute('aria-expanded', 'false');
}
</script>
